mapper.select:
SELECT m.name AS member_name, g.name AS group_name, la.type, la.reason, la.image, la.start, la.end, la.status, la.senior_id, la.feedback, la.create_time FROM leaveapply la LEFT JOIN member m ON la.member_id = m.id LEFT JOIN `group` g ON m.group_id = g.id LEFT JOIN senior s ON la.senior_id = s.id
AND m.name LIKE CONCAT('%',#{dto.name},'%')
AND la.type = #{dto.type}
AND la.status = #{dto.status}
AND la.start >= #{dto.start}
AND la.end <= #{dto.end}
ORDER BY la.create_time DESC

mapper.update:
UPDATE leaveapply
SET
    status = #{status},
    feedback = #{feedback}
WHERE id = #{id}
